# area: overloads
# hypothesis: Overloads on Literal[True], Literal[False] and a bool fallback resolve a bool union argument by union expansion to str | bytes, and a Literal['bin'] string selects the bytes overload.
from typing import Literal, overload, reveal_type


@overload
def load(raw: Literal[True]) -> bytes: ...
@overload
def load(raw: Literal[False] = ...) -> str: ...
@overload
def load(raw: bool) -> str | bytes: ...
def load(raw: bool = False) -> str | bytes:
    return b'x' if raw else 'x'


@overload
def fetch(kind: Literal['bin']) -> bytes: ...
@overload
def fetch(kind: Literal['txt']) -> str: ...
def fetch(kind: str) -> str | bytes:
    return b'x' if kind == 'bin' else 'x'


def pick(flag: bool, lit: Literal[True, False]) -> None:
    reveal_type(load(True))
    reveal_type(load())
    reveal_type(load(flag))
    reveal_type(load(lit))  # union expansion: str | bytes
    reveal_type(fetch('bin'))


pick(True, False)
print(load(True), load(), fetch('bin'), fetch('txt'))
